tests:
test({ sr: 'obrće običan tekst', en: 'reverses plain text' }, () => {
  expect(reverseString('abc')).toBe('cba');
});
test({ sr: 'čuva razmake', en: 'keeps spaces' }, () => {
  expect(reverseString('a b')).toBe('b a');
});
test({ sr: 'prazan string daje prazan string', en: 'an empty string gives an empty string' }, () => {
  expect(reverseString('')).toBe('');
});

hiddenTests:
test('a palindrome stays the same', () => {
  expect(reverseString('level')).toBe('level');
});
test('a single character', () => {
  expect(reverseString('x')).toBe('x');
});
test('emoji are not broken', () => {
  expect(reverseString('a😀b')).toBe('b😀a');
});
test('spaces at the start and the end are kept', () => {
  expect(reverseString(' ab ')).toBe(' ba ');
});
